"""Generate docs/QUERIES.md from the `// purpose:` and `// algorithm:` headers of every .cypher file."""

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT / "backend"))

from rootcause.graph.registry import load_all  # noqa: E402


def main() -> None:
    queries = load_all()
    lines = ["# Queries and algorithms", "",
             "Every graph query RootCause runs lives in a named file under `backend/rootcause/graph/queries/`. "
             "This table is generated by `make queries-doc` from each file's header.", "",
             "FalkorDB algorithms we depend on: "
             + ", ".join(sorted({q.algorithm for q in queries.values() if q.algorithm != "-"})) + ".", "",
             "| name | file | purpose | algorithm |", "|---|---|---|---|"]
    for name, q in queries.items():
        lines.append(f"| `{name}` | [{name}.cypher](../backend/rootcause/graph/queries/{name}.cypher) | {q.purpose} | "
                     f"{q.algorithm} |")
    (ROOT / "docs" / "QUERIES.md").write_text("\n".join(lines) + "\n", encoding="utf-8")
    print(f"wrote {len(queries)} queries to docs/QUERIES.md")


if __name__ == "__main__":
    main()
